uit( data=genome_metadata, geom=geom_bar, mapping = aes(x=completeness, y=genome, fill=contamination), offset = 0.3, orientation=&quot;y&quot;, stat=&quot;identity&quot;) circular_tree &lt;- circular_tree + new_scale_fill() circular_tree &lt;- gheatmap(circular_tree, newspecies_table, offset=0.5, width=0.05, colnames=FALSE) + scale_fill_manual(values=c(&quot;#f4f4f4&quot;,&quot;#666666&quot;)) # Add text circular_tree &lt;- circular_tree + annotate(&#39;text&#39;, x=2.9, y=0, label=&#39; Phylum&#39;, family=&#39;ArialMT&#39;, size=3.5) + annotate(&#39;text&#39;, x=3.6, y=0, label=&#39; Genome quality&#39;, family=&#39;ArialMT&#39;, size=3.5) + annotate(&#39;text&#39;, x=3.2, y=0, label=&#39; New species&#39;, family=&#39;ArialMT&#39;, size=3.5) #Plot circular tree circular_tree %&gt;% open_tree(30) %&gt;% rotate_tree(90) 4.2 Catalogue summary # Manuscript: 313 MAGs, 15 phyla (Bacillota A 119, Bacteroidota 77, Pseudomonadota 34), # 36 annotated at species level (most Pseudomonadota, 33%), new species discovery rate over 88%. n_mags &lt;- nrow(genome_metadata) cat(&quot;MAGs in catalogue:&quot;, n_mags, &quot;
